import urllib.request
import urllib.error
import json

def http_json_request(url: str, method: str = 'GET', payload: dict = None, timeout: float = 10.0) -> dict:
    headers = {'User-Agent': 'Awesome-Stdlib/1.0', 'Accept': 'application/json'}
    data = json.dumps(payload).encode('utf-8') if payload else None
    if data:
        headers['Content-Type'] = 'application/json'
    req = urllib.request.Request(url, data=data, headers=headers, method=method.upper())
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode('utf-8'))

import graphlib

def compute_execution_order(dag: dict[str, set[str]]) -> list[str]:
    ts = graphlib.TopologicalSorter(dag)
    return list(ts.static_order())

import hmac
import hashlib
import json

def sign_canonical_receipt(secret_key: bytes, payload: dict) -> str:
    canonical_bytes = json.dumps(payload, separators=(',', ':'), sort_keys=True, ensure_ascii=False).encode('utf-8')
    return hmac.new(secret_key, canonical_bytes, hashlib.sha256).hexdigest()
